        ],
        "unknowns": [
          {
            "issue": "没有相同任务的终端或图形客户端对照",
            "impact": "不能量化少切换界面是否带来更少错误或更快交付",
            "next_step": "在相同仓库和任务清单下比较完成率、用时与错误回退，记录人工复核时间"
